use std::collections::HashMap;

// ---- Structs for examples ----
#[derive(Debug, Clone)]
struct Player {
    name: String,
    health: i32,
    attack: i32,
    defense: i32,
    level: i32,
}

impl Player {
    fn new(name: &str, health: i32, attack: i32, defense: i32, level: i32) -> Self {
        Player {
            name: name.to_string(),
            health,
            attack,
            defense,
            level,
        }
    }
}

fn main() {
    let players = vec![
        Player::new("Hero", 100, 20, 15, 5),
        Player::new("Aragorn", 120, 25, 18, 8),
        Player::new("Gandalf", 80, 15, 10, 6),
        Player::new("Legolas", 90, 22, 14, 7),
        Player::new("Gimli", 110, 23, 20, 6),
    ];

    // ---- map: transform each element ----
    // Get all player names
    let names: Vec<String> = players.iter().map(|p| p.name.clone()).collect();
    println!("Names: {:?}", names);

    // Get total attack power
    let total_attack: i32 = players.iter().map(|p| p.attack).sum();
    println!("Total attack: {}", total_attack);

    // ---- filter: keep matching elements ----
    // Players with health > 100
    let healthy_players: Vec<&Player> = players.iter().filter(|p| p.health > 100).collect();
    println!("\nHealthy players (HP > 100):");
    for p in &healthy_players {
        println!("  {}: HP {}", p.name, p.health);
    }

    // Players with level >= 7
    let high_level: Vec<&Player> = players.iter().filter(|p| p.level >= 7).collect();
    println!("\nHigh level players (Lv >= 7):");
    for p in &high_level {
        println!("  {}: Lv {}", p.name, p.level);
    }

    // ---- filter + map ----
    // Get names of players with high attack
    let strong_names: Vec<String> = players
        .iter()
        .filter(|p| p.attack >= 20)
        .map(|p| p.name.clone())
        .collect();
    println!("\nStrong players (ATK >= 20): {:?}", strong_names);

    // ---- map with enumerate ----
    // Add index to players
    let indexed: Vec<(usize, &Player)> = players.iter().enumerate().collect();
    println!("\nIndexed players:");
    for (i, p) in &indexed {
        println!("  {}: {} (Lv {})", i, p.name, p.level);
    }

    // ---- collect into HashMap ----
    let player_map: HashMap<String, i32> = players
        .iter()
        .map(|p| (p.name.clone(), p.health))
        .collect();
    println!("\nPlayer map: {:?}", player_map);

    // ---- filter_map: filter and transform in one step ----
    // Get only players with even level
    let even_level_names: Vec<String> = players
        .iter()
        .filter_map(|p| {
            if p.level % 2 == 0 {
                Some(p.name.clone())
            } else {
                None
            }
        })
        .collect();
    println!("\nEven level players: {:?}", even_level_names);

    // ---- Chaining multiple adapters ----
    // Get names of players with health > 90 and level >= 6, sorted by health
    let mut filtered: Vec<String> = players
        .iter()
        .filter(|p| p.health > 90 && p.level >= 6)
        .map(|p| p.name.clone())
        .collect();
    filtered.sort();
    println!("\nFiltered players (HP > 90, Lv >= 6): {:?}", filtered);

    // ---- Using collect with different types ----
    let levels: Vec<i32> = players.iter().map(|p| p.level).collect();
    let avg_level: f64 = levels.iter().sum::<i32>() as f64 / levels.len() as f64;
    println!("\nAverage level: {:.2}", avg_level);
}

